#!/bin/bash
action="${1%%:*}" file="${1#*:}" filename=$(basename "$file")
case "$action" in "reveal") open -R "$file" osascript -e "display notification \"Revealed in Finder\" with title \"Screenshot: $filename\"" ;; "delete") osascript -e "tell application \"System Events\" to delete alias POSIX file \"$file\"" osascript -e "display notification \"Screenshot deleted\" with title \"$filename\"" ;; "open") open -a Preview "$file" osascript -e "display notification \"Opened in Preview\" with title \"Screenshot: $filename\"" ;; *) # Default: copy to clipboard osascript -e "set the clipboard to (read (POSIX file \"$1\") as {«class PNGf»})" osascript -e "display notification \"Copied to clipboard\" with title \"Screenshot: $(basename \"$1\")\"" ;; esac

#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Alfred Workflow Script Filter for Screenshot Gallery
This script generates JSON output for Alfred to display screenshots as a gallery
"""

import json
import os
import sys
from datetime import datetime
from pathlib import Path

# Configuration - Change this to your screenshots directory
SCREENSHOTS_DIR = os.path.expanduser("~/Desktop/.Screenshots")  # Hidden screenshots folder
# You can change this to any directory, e.g.:
# SCREENSHOTS_DIR = os.path.expanduser("~/Pictures/Screenshots")

# Supported image formats
IMAGE_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.gif', '.bmp', '.tiff', '.webp'}

def get_file_size(file_path):
    """Get human-readable file size"""
    size = os.path.getsize(file_path)
    for unit in ['B', 'KB', 'MB', 'GB']:
        if size < 1024.0:
            return f"{size:.1f} {unit}"
        size /= 1024.0
    return f"{size:.1f} TB"

def get_screenshots(directory, query=""):
    """Get all screenshots from the specified directory"""
    screenshots = []

    # Debug mode - set to True to see diagnostic info
    DEBUG = False

    try:
        path = Path(directory)
        if not path.exists():
            return [{
                "title": "Directory not found",
                "subtitle": f"The directory {directory} does not exist",
                "valid": False,
                "icon": {
                    "path": "/System/Library/CoreServices/CoreTypes.bundle/Contents/Resources/AlertCautionIcon.icns"
                }
            }]

        # Get all image files (including hidden files)
        files = []
        for ext in IMAGE_EXTENSIONS:
            # Standard pattern
            files.extend(path.glob(f"*{ext}"))
            files.extend(path.glob(f"*{ext.upper()}"))
            # Also check for files starting with dot (hidden files)
            files.extend(path.glob(f".*{ext}"))
            files.extend(path.glob(f".*{ext.upper()}"))

        # Remove duplicates
        files = list(set(files))

        if DEBUG:
            # Add debug info as first item
            screenshots.append({
                "title": f"Debug: Found {len(files)} files",
                "subtitle": f"Directory: {directory}",
                "valid": False,
                "icon": {
                    "path": "/System/Library/CoreServices/CoreTypes.bundle/Contents/Resources/AlertNoteIcon.icns"
                }
            })

        # Sort by modification time (newest first)
        files.sort(key=lambda x: x.stat().st_mtime, reverse=True)

        # Filter by query if provided
        if query:
            query_lower = query.lower()
            files = [f for f in files if query_lower in f.name.lower()]

        # Optional: Limit number of files for performance
        # Uncomment the line below if you want to limit results (e.g., for better performance)
        # files = files[:50]

        # Note: Showing all screenshots may impact performance if you have hundreds of files
        # Alfred handles large result sets well, but consider enabling the limit if needed

        for file_path in files:
            stat = file_path.stat()
            mod_time = datetime.fromtimestamp(stat.st_mtime)

            # Create Alfred item
            item = {
                "uid": str(file_path),
                "title": file_path.name,
                "subtitle": f"{get_file_size(file_path)} • {mod_time.strftime('%Y-%m-%d %H:%M')}",
                "arg": str(file_path),
                "valid": True,
                "icon": {
                    "path": str(file_path)
                },
                "quicklookurl": str(file_path),
                "mods": {
                    "cmd": {
                        "subtitle": "Reveal in Finder",
                        "arg": f"reveal:{file_path}"
                    },
                    "alt": {
                        "subtitle": "Delete screenshot",
                        "arg": f"delete:{file_path}"
                    },
                    "ctrl": {
                        "subtitle": "Open in Preview",
                        "arg": f"open:{file_path}"
                    }
                }
            }
            screenshots.append(item)

        if not screenshots:
            return [{
                "title": "No screenshots found",
                "subtitle": f"No images found in {directory}",
                "valid": False,
                "icon": {
                    "path": "/System/Library/CoreServices/CoreTypes.bundle/Contents/Resources/GenericFolderIcon.icns"
                }
            }]

    except Exception as e:
        return [{
            "title": "Error",
            "subtitle": str(e),
            "valid": False,
            "icon": {
                "path": "/System/Library/CoreServices/CoreTypes.bundle/Contents/Resources/AlertStopIcon.icns"
            }
        }]

    return screenshots

def main():
    # Get query from Alfred (if any)
    query = sys.argv[1] if len(sys.argv) > 1 else ""

    # Get screenshots
    items = get_screenshots(SCREENSHOTS_DIR, query)

    # Output JSON for Alfred
    output = {"items": items}
    print(json.dumps(output))

if __name__ == "__main__":
    main()
